package cryptocompat

import (
	"os"
	"os/exec"
	"strings"
	"testing"
)

const testSecret = "test-vault-secret"
const testPlaintext = "Kova compatible: 文件"

func TestNativeFixtures(t *testing.T) {
	// Generated by the C++ vault_encrypt/sign_url_payload implementation.
	const encrypted = "enc:v1:MZUzkeM_0qJMrNt9u-GQQf2DI_Jh8xYwKmruE32y-CzQ1I4FzP6v8zYhhZxsRLCuQFRF"
	const signed = "CF4ipYBTLU1feFpdk-o29cBbUbNBGgOgrnSWimrUdys:2000000000"
	got, err := DecryptVault(testSecret, encrypted)
	if err != nil || got != testPlaintext {
		t.Fatalf("native vault: %q %v", got, err)
	}
	if got := SignURL(testSecret, "/local/a b.txt", 2000000000); got != signed {
		t.Fatalf("native signature: %q", got)
	}
	if !VerifyURL(testSecret, "/local/a b.txt", signed, 2000000000) {
		t.Fatal("expiry boundary rejected")
	}
	if VerifyURL(testSecret, "/local/a b.txt", signed, 2000000001) {
		t.Fatal("expired signature accepted")
	}
}

func TestVaultRoundTripAndTamper(t *testing.T) {
	a, err := EncryptVault(testSecret, testPlaintext)
	if err != nil {
		t.Fatal(err)
	}
	b, err := EncryptVault(testSecret, testPlaintext)
	if err != nil {
		t.Fatal(err)
	}
	if a == b {
		t.Fatal("nonce reused")
	}
	plain, err := DecryptVault(testSecret, a)
	if err != nil || plain != testPlaintext {
		t.Fatal(plain, err)
	}
	if _, err := DecryptVault("wrong secret", a); err == nil {
		t.Fatal("wrong key accepted")
	}
	if _, err := DecryptVault(testSecret, a[:len(a)-2]+"AA"); err == nil {
		t.Fatal("tampering accepted")
	}
	for _, v := range []string{"enc:v1:", "enc:v1:not-valid!", "enc:v1:AAAA"} {
		if _, err := DecryptVault(testSecret, v); err == nil {
			t.Fatalf("invalid input accepted: %q", v)
		}
	}
	for _, v := range []string{"", "legacy plaintext", a} {
		got, err := EncryptVault(testSecret, v)
		if v == a && (got != v || err != nil) {
			t.Fatal("encoded value not preserved")
		}
		if v == "" && (got != v || err != nil) {
			t.Fatal("empty value not preserved")
		}
		if v == "legacy plaintext" {
			plain, err := DecryptVault(testSecret, v)
			if err != nil || plain != v {
				t.Fatal("legacy plaintext")
			}
		}
	}
}

func TestURLInvalid(t *testing.T) {
	for _, sig := range []string{"", ":0", "x:", "x:-1", "x:999999999999999999999", SignURL("secret", "/a", -1), SignURL("secret", "/a", 1) + "0", SignURL("secret", "/a", 0) + "0"} {
		if VerifyURL("secret", "/a", sig, 100) {
			t.Fatalf("accepted %q", sig)
		}
	}
	sig := SignURL("secret", "/a", 0)
	if !VerifyURL("secret", "/a", sig, 100) || VerifyURL("secret", "/b", sig, 100) || VerifyURL("wrong", "/a", sig, 100) {
		t.Fatal("signature checks failed")
	}
}

func TestNativeRoundTrip(t *testing.T) {
	binary := os.Getenv("KOVA_NATIVE_CRYPTO_FIXTURE")
	if binary == "" {
		t.Skip("set KOVA_NATIVE_CRYPTO_FIXTURE for native interoperability")
	}
	run := func(mode, input string) string {
		t.Helper()
		cmd := exec.Command(binary, mode)
		cmd.Stdin = strings.NewReader(input)
		out, err := cmd.Output()
		if err != nil {
			t.Fatalf("native %s: %v", mode, err)
		}
		return string(out)
	}
	cppEncrypted := run("encrypt", "")
	got, err := DecryptVault(testSecret, cppEncrypted)
	if err != nil || got != testPlaintext {
		t.Fatalf("Go failed to decrypt native value: %q %v", got, err)
	}
	goEncrypted, err := EncryptVault(testSecret, testPlaintext)
	if err != nil {
		t.Fatal(err)
	}
	if got := run("decrypt", goEncrypted+"\n"); got != testPlaintext {
		t.Fatalf("native failed to decrypt Go value: %q", got)
	}
	if got := run("sign", ""); got != SignURL(testSecret, "/local/a b.txt", 2000000000) {
		t.Fatalf("signature mismatch: %q", got)
	}
}

func FuzzDecryptVault(f *testing.F) {
	for _, s := range []string{"", "enc:v1:", "plain", "enc:v1:AAAA"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) { _, _ = DecryptVault(testSecret, s) })
}
